import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { badgeClassNameByVariant } from "./view";
import type { BadgeVariant } from "./view";

export type { BadgeVariant };

export {
  badgeClassName,
  badgeClassNameByVariant,
  destructiveBadgeClassName,
  ghostBadgeClassName,
  linkBadgeClassName,
  outlineBadgeClassName,
  secondaryBadgeClassName,
} from "./view";

export type ViewConfig = Readonly<{
  label: string;
  variant?: BadgeVariant;
  className?: string;
}>;

export type ContentViewConfig = Readonly<{
  children: readonly (Html | string)[];
  variant?: BadgeVariant;
  className?: string;
}>;

const classNamesForVariant = (
  variant: BadgeVariant,
  className?: string
): string =>
  [badgeClassNameByVariant(variant), className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const contentView = <ParentMessage>({
  children,
  variant = "Default",
  className,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span([h.Class(classNamesForVariant(variant, className))], children);
};

export const view = <ParentMessage>({
  label,
  variant = "Default",
  className,
}: ViewConfig): Html =>
  contentView<ParentMessage>({
    children: [label],
    variant,
    ...(className === undefined ? {} : { className }),
  });

export type BadgeVariant =
  | "Default"
  | "Secondary"
  | "Destructive"
  | "Outline"
  | "Ghost"
  | "Link";

export const badgeClassName =
  "inline-flex items-center rounded-md bg-accent-600 px-2 py-1 text-xs font-medium text-white";

export const secondaryBadgeClassName =
  "inline-flex items-center rounded-md bg-gray-100 px-2 py-1 text-xs font-medium text-gray-700";

export const destructiveBadgeClassName =
  "inline-flex items-center rounded-md bg-red-600 px-2 py-1 text-xs font-medium text-white";

export const outlineBadgeClassName =
  "inline-flex items-center rounded-md border border-gray-300 bg-white px-2 py-1 text-xs font-medium text-gray-700";

export const ghostBadgeClassName =
  "inline-flex items-center rounded-md bg-transparent px-2 py-1 text-xs font-medium text-gray-700";

export const linkBadgeClassName =
  "inline-flex items-center rounded-md bg-transparent px-0 py-1 text-xs font-medium text-accent-700 underline-offset-4 hover:underline";

export const badgeClassNameByVariant = (
  variant: BadgeVariant = "Default"
): string => {
  if (variant === "Secondary") {
    return secondaryBadgeClassName;
  }

  if (variant === "Destructive") {
    return destructiveBadgeClassName;
  }

  if (variant === "Outline") {
    return outlineBadgeClassName;
  }

  if (variant === "Ghost") {
    return ghostBadgeClassName;
  }

  if (variant === "Link") {
    return linkBadgeClassName;
  }

  return badgeClassName;
};

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Badge from "./index";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [h.Class("flex flex-wrap gap-2")],
    [
      Badge.view({ label: "Default" }),
      Badge.view({ label: "Secondary", variant: "Secondary" }),
      Badge.view({ label: "Destructive", variant: "Destructive" }),
      Badge.view({ label: "Outline", variant: "Outline" }),
    ]
  );
};

describe("Badge registry view", () => {
  test("renders every documented variant", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Default")).toExist(),
      Scene.expect(Scene.text("Secondary")).toExist(),
      Scene.expect(Scene.text("Destructive")).toExist(),
      Scene.expect(Scene.text("Outline")).toExist()
    );
  });
});
